def add_months(moment, months):
    """points.models.add_months, frozen here as this migration needs it."""
    month_index = moment.month - 1 + months
    year = moment.year + month_index // 12
    month = month_index % 12 + 1
    day = min(moment.day, calendar.monthrange(year, month)[1])
    return moment.replace(year=year, month=month, day=day)


def date_live_listings(apps, schema_editor):
    """
    A Limited Shop Owner's products already live get a full first period from
    today, rather than ending at once because they were published long ago.
    """
    Product = apps.get_model("shop", "Product")
    Product.objects.filter(
        status="PUBLISHED",
        live_until__isnull=True,
        shop__owner__seller_type="LIMITED_SHOP_OWNER",
    ).update(live_until=add_months(timezone.now(), FIRST_PERIOD_MONTHS))


